      "simulador_virtual": "<div class='sim-phet' data-modo='trajetoria' style='padding:24px;border-radius:20px;background:#0f172a;color:#f8fafc;border:1px solid #334155;position:relative;'><div style='display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:16px;'><div><div style='font-size:0.8em;color:#38bdf8;font-weight:800;text-transform:uppercase;letter-spacing:1px;'>🎮 Laboratório Arcade Interativo (Com Som &amp; Física)</div><div style='font-size:1.22em;font-weight:800;margin-top:2px;'>Diversidade linguística e cultural do mundo hispânico</div></div><div style='display:flex;flex-wrap:wrap;gap:8px;align-items:center;'><select onchange='window.mudarGravidadeSim(this)' style='background:#1e293b;color:#fbbf24;border:1px solid #fbbf24;border-radius:999px;padding:8px 14px;font-size:0.84em;font-weight:800;cursor:pointer;'><option value='9.8'>🌍 Terra (9.8 m/s²)</option><option value='1.6'>🌕 Lua (1.6 m/s²)</option><option value='3.7'>🔴 Marte (3.7 m/s²)</option><option value='24.8'>🪐 Júpiter (24.8 m/s²)</option></select><button type='button' onclick='window.alternarTelaCheiaSim(this)' style='background:#6366f1;color:#ffffff;border:none;padding:9px 16px;border-radius:999px;font-weight:800;cursor:pointer;font-size:0.86em;'>⛶ Tela Cheia</button></div></div><div style='display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px;'><button type='button' data-m='trajetoria' onclick='window.mudarModoSim(this)' style='background:linear-gradient(90deg,#38bdf8,#818cf8);color:#020617;border:none;padding:9px 15px;border-radius:999px;font-weight:800;cursor:pointer;font-size:0.86em;'>🎯 Canhão &amp; Alvo</button><button type='button' data-m='ondas' onclick='window.mudarModoSim(this)' style='background:#1e293b;color:#f8fafc;border:1px solid #475569;padding:9px 15px;border-radius:999px;font-weight:700;cursor:pointer;font-size:0.86em;'>🌊 Ondas &amp; Interferência</button><button type='button' data-m='particulas' onclick='window.mudarModoSim(this)' style='background:#1e293b;color:#f8fafc;border:1px solid #475569;padding:9px 15px;border-radius:999px;font-weight:700;cursor:pointer;font-size:0.86em;'>⚛️ Reator Térmico</button><button type='button' data-m='orbita' onclick='window.mudarModoSim(this)' style='background:#1e293b;color:#f8fafc;border:1px solid #475569;padding:9px 15px;border-radius:999px;font-weight:700;cursor:pointer;font-size:0.86em;'>🪐 Órbita &amp; Gravidade</button><button type='button' data-m='pendulo' onclick='window.mudarModoSim(this)' style='background:#1e293b;color:#f8fafc;border:1px solid #475569;padding:9px 15px;border-radius:999px;font-weight:700;cursor:pointer;font-size:0.86em;'>⏱️ Pêndulo &amp; Energia</button><button type='button' data-m='circuito' onclick='window.mudarModoSim(this)' style='background:#1e293b;color:#f8fafc;border:1px solid #475569;padding:9px 15px;border-radius:999px;font-weight:700;cursor:pointer;font-size:0.86em;'>⚡ Circuito Elétrico</button></div><div style='background:#020617;border:2px solid #334155;border-radius:18px;padding:12px;margin-bottom:16px;'><canvas class='sim-canvas' width='900' height='380' onclick='window.rodarSimCanvas(this)' style='width:100%;height:380px;object-fit:contain;border-radius:12px;display:block;background:#020617;cursor:crosshair;'></canvas><div style='display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;align-items:center;margin-top:12px;padding:0 6px;'><div style='display:flex;gap:10px;'><button type='button' onclick='window.rodarSimCanvas(this)' style='background:#10b981;color:#022c22;border:none;padding:10px 24px;border-radius:999px;font-weight:800;font-size:0.95em;cursor:pointer;'>▶ Disparar / Simular</button><button type='button' onclick='window.resetarSimCanvas(this)' style='background:#334155;color:#f8fafc;border:none;padding:10px 18px;border-radius:999px;font-weight:700;font-size:0.9em;cursor:pointer;'>🔄 Novo Alvo</button></div><div class='sim-placar' style='background:#1e293b;border:1px solid #475569;padding:8px 16px;border-radius:999px;font-size:0.9em;font-weight:800;color:#fbbf24;'>🏆 0 pts • Arraste na tela para mirar e clique para atirar!</div></div></div><div style='display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px;background:#1e293b;border:1px solid #334155;border-radius:16px;padding:18px;margin-bottom:14px;'><div><div style='display:flex;justify-content:space-between;font-size:0.95em;margin-bottom:8px;'><span>⚡ <strong>Força / Energia / Voltagem:</strong></span><strong class='lbl-pot' style='color:#38bdf8;font-size:1.05em;'>65</strong></div><input type='range' class='inp-pot' min='20' max='100' value='65' oninput='window.desenharPreviewSim(this)' style='width:100%;height:8px;accent-color:#38bdf8;cursor:pointer;' /></div><div><div style='display:flex;justify-content:space-between;font-size:0.95em;margin-bottom:8px;'><span>📐 <strong>Ângulo / Frequência / Resistência:</strong></span><strong class='lbl-ang' style='color:#fbbf24;font-size:1.05em;'>45°</strong></div><input type='range' class='inp-ang' min='10' max='85' value='45' oninput='window.desenharPreviewSim(this)' style='width:100%;height:8px;accent-color:#fbbf24;cursor:pointer;' /></div></div><div class='sim-feedback' style='background:rgba(16,185,129,0.14);border-left:4px solid #34d399;border-radius:12px;padding:14px 18px;font-size:0.96em;line-height:1.65;color:#a7f3d0;'>💡 <strong>Dica:</strong> Você pode <strong>arrastar o mouse direto sobre a tela</strong> para mirar o canhão ou usar os controles acima. Acerte 3 vezes seguidas para liberar barreiras e alvos móveis!</div></div>",
